import{_ as t}from"./chunks/difficulty_easy.76S4H_Nf.js";import{_ as i}from"./chunks/position_fixed.t2m3lWVy.js";import{_ as o,a as r}from"./chunks/orbit_mc.CrPnT6Yf.js";import{_ as a,o as l,c as n,al as d}from"./chunks/framework.7vp1BMOE.js";const v=JSON.parse('{"title":"环绕模式 （多旋翼）","description":"","frontmatter":{},"headers":[],"relativePath":"zh/flight_modes_mc/orbit.md","filePath":"zh/flight_modes_mc/orbit.md"}'),s={name:"zh/flight_modes_mc/orbit.md"};function m(c,e,_,h,u,p){return l(),n("div",null,[...e[0]||(e[0]=[d('<h1 id="环绕模式-多旋翼" tabindex="-1">环绕模式 （多旋翼） <a class="header-anchor" href="#环绕模式-多旋翼" aria-label="Permalink to &quot;环绕模式 （多旋翼）&quot;">​</a></h1><p><img src="'+t+'" title="Easy to fly" width="30px"> <img src="'+i+'" title="Position fix required (e.g. GPS)" width="30px"></p><p>The <em>Orbit</em> guided flight mode allows you to command a multicopter (or VTOL in multicopter mode) to fly in a circle at a particular location, by <a href="https://mavlink.io/en/messages/common.html#ORBIT_YAW_BEHAVIOUR" target="_blank" rel="noreferrer">default</a> yawing so that it always faces towards the center.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li>Mode is automatic - no user intervention is <em>required</em> to control the vehicle.</li><li>Mode requires at least a valid local position estimate (does not require a global position). <ul><li>Flying vehicles will failsafe if they lose the position estimate.</li></ul></li><li>Mode prevents arming (vehicle cannot be armed while this mode is selected).</li><li>Mode requires wind and flight time are within allowed limits (specified via parameters).</li><li>Mode is currently only supported on multicopter (or VTOL in MC mode).</li><li>RC stick movement can control ascent/descent and orbit speed and direction.</li><li>Mode can be triggered using the <a href="https://mavlink.io/en/messages/common.html#MMAV_CMD_DO_ORBIT" target="_blank" rel="noreferrer">MAV_CMD_DO_ORBIT</a> MAVLink command.</li></ul></div><h3 id="mode-requirements" tabindex="-1">Mode Requirements <a class="header-anchor" href="#mode-requirements" aria-label="Permalink to &quot;Mode Requirements&quot;">​</a></h3><p>The following requirements must be met to arm in this mode, or to switch to this mode when it is armed.</p><ul><li><a href="./../flight_modes/mode_requirements#mode_req_angular_velocity"><code>mode_req_angular_velocity</code></a> — Angular velocity</li><li><a href="./../flight_modes/mode_requirements#mode_req_attitude"><code>mode_req_attitude</code></a> — Attitude/pose</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_alt"><code>mode_req_local_alt</code></a> — Local altitude relative to EKF2 origin (&#39;0&#39;) position</li><li><a href="./../flight_modes/mode_requirements#mode_req_local_position"><code>mode_req_local_position</code></a> — Position relative to EKF2 origin (&#39;0&#39;) point</li><li><a href="./../flight_modes/mode_requirements#mode_req_prevent_arming"><code>mode_req_prevent_arming</code></a> — Mode prevents arming</li><li><a href="./../flight_modes/mode_requirements#mode_req_wind_and_flight_time_compliance"><code>mode_req_wind_and_flight_time_compliance</code></a> — Safety compliance limits on wind and flight time.</li></ul><h2 id="综述" tabindex="-1">综述 <a class="header-anchor" href="#综述" aria-label="Permalink to &quot;综述&quot;">​</a></h2><p><img src="'+o+'" alt="Orbit Mode - MC"></p><p><em>QGroundControl</em> (or other compatible GCS or MAVLink API) is <em>required</em> to enable the mode, and to set the center position, initial radius and altitude of the orbit. Once enabled the vehicle will fly as fast as possible to the closest point on the commanded circle trajectory and do a slow (1m/s) clockwise orbit on the planned circle, facing the center.</p><p>Instructions for how to start an orbit can be found here: <a href="https://docs.qgroundcontrol.com/master/en/qgc-user-guide/fly_view/fly_view.html#orbit" target="_blank" rel="noreferrer">FlyView &gt; Orbit Location</a> (<em>QGroundControl</em> guide).</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The use of an RC control is <em>optional</em>. If no RC control is present the orbit will proceed as described above. 无法使用遥控来启动该模式（如果使用遥控切换该模式，无人机会处于空闲状态）。</p></div><p>遥控可以用于改变绕圈的高度，半径，速度和绕圈方向：</p><ul><li><strong>Left stick:</strong><ul><li><em>up/down:</em> controls speed of ascent/descent, as in <a href="./../flight_modes_mc/position">Position mode</a>. When in center deadzone, altitude is locked.</li><li><em>left/right:</em> no effect.</li></ul></li><li><strong>Right stick:</strong><ul><li><em>left/right:</em> controls acceleration of orbit in clockwise/counter-clockwise directions. When centered the current speed is locked. <ul><li>Maximum velocity is <a href="#MPC_XY_VEL_MAX">MPC_XY_VEL_MAX</a> and further limited to keep the centripetal acceleration below 2m/s^2.</li></ul></li><li><em>up/down:</em> controls orbit radius (smaller/bigger). When centered the current radius is locked. <ul><li>最小半径是 1 米。 Maximum radius is <a href="#MC_ORBIT_RAD_MAX">MC_ORBIT_RAD_MAX</a>.</li></ul></li></ul></li></ul><p>The diagram below shows the mode behaviour visually (for a <a href="./../getting_started/rc_transmitter_receiver#transmitter_modes">mode 2 transmitter</a>).</p><p><img src="'+r+'" alt="Orbit Mode - MC"></p><p>切换到其他飞行模式（使用遥控或 QGC 地面站）可以停止此模式。</p><h2 id="参数-限制" tabindex="-1">参数/限制 <a class="header-anchor" href="#参数-限制" aria-label="Permalink to &quot;参数/限制&quot;">​</a></h2><p>该模式受以下参数影响：</p><table tabindex="0"><thead><tr><th>Parameter</th><th>描述</th></tr></thead><tbody><tr><td><a id="MC_ORBIT_RAD_MAX"></a><a href="./../advanced_config/parameter_reference#MC_ORBIT_RAD_MAX">MC_ORBIT_RAD_MAX</a></td><td>Maximum radius of orbit. Default: 1000m.</td></tr><tr><td><a id="MC_ORBIT_YAW_MOD"></a><a href="./../advanced_config/parameter_reference#MC_ORBIT_YAW_MOD">MC_ORBIT_YAW_MOD</a></td><td>Yaw behaviour during orbit flight. Default: Front to Circle Center.</td></tr><tr><td><a id="MPC_XY_VEL_MAX"></a><a href="./../advanced_config/parameter_reference#MPC_XY_VEL_MAX">MPC_XY_VEL_MAX</a></td><td>Tangential speed limit. Stick input won&#39;t accelerate beyond this limit. Higher commands are accepted but capped.</td></tr></tbody></table><p>下面的限制是写死的：</p><ul><li>Initial/default rotation is 1m/s in a clockwise direction.</li><li>The maximum acceleration is limited to 2m/s^2, with priority on keeping the commanded circle trajectory rather than commanded ground speed (i.e. the vehicle will slow down in order to achieve the correct circle if the acceleration exceeds 2m/s^2).</li></ul><h2 id="mavlink-消息-开发者" tabindex="-1">MAVLink 消息 （开发者） <a class="header-anchor" href="#mavlink-消息-开发者" aria-label="Permalink to &quot;MAVLink 消息 （开发者）&quot;">​</a></h2><p>环绕模式使用以下 MAVLink 命令：</p><ul><li><a href="https://mavlink.io/en/messages/common.html#MAV_CMD_DO_ORBIT" target="_blank" rel="noreferrer">MAV_CMD_DO_ORBIT</a> - Start an orbit with specified center point, radius, direction, altitude, speed and <a href="https://mavlink.io/en/messages/common.html#ORBIT_YAW_BEHAVIOUR" target="_blank" rel="noreferrer">yaw direction</a>. The same defaults and limits apply. When exceeding limits the command is accepted but velocity and radius capped.</li><li><a href="https://mavlink.io/en/messages/common.html#ORBIT_EXECUTION_STATUS" target="_blank" rel="noreferrer">ORBIT_EXECUTION_STATUS</a> - Orbit status emitted during orbit to update GCS of current orbit parameters (these may be changed by the RC controller).</li></ul>',25)])])}const k=a(s,[["render",m]]);export{v as __pageData,k as default};
